package com.leafreader.app;
import java.util.*;
import org.json.*;
public final class Book {
 public String id,title,author="本地书籍",format="TXT";public int position=0;public long lastRead=0,added=System.currentTimeMillis();public List<Core.Unit> units=new ArrayList<>();
 public void add(String text,String chapter,boolean heading){for(String part:Core.split(text,260))units.add(new Core.Unit(part,chapter,heading));}
 public JSONObject toJson() throws JSONException {JSONObject j=new JSONObject();j.put("id",id);j.put("title",title);j.put("author",author);j.put("format",format);JSONArray a=new JSONArray();for(Core.Unit u:units){JSONObject x=new JSONObject();x.put("text",u.text);x.put("chapter",u.chapter);x.put("heading",u.heading);a.put(x);}j.put("units",a);return j;}
 public static Book fromJson(JSONObject j)throws JSONException{Book b=new Book();b.id=j.getString("id");b.title=j.getString("title");b.author=j.optString("author","本地书籍");b.format=j.optString("format","TXT");JSONArray a=j.getJSONArray("units");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);b.units.add(new Core.Unit(x.getString("text"),x.optString("chapter","正文"),x.optBoolean("heading")));}return b;}
 public static Book demo(){Book b=new Book();b.id="welcome-native-v1";b.title="从这一页开始";b.author="页间 · 原生阅读指南";b.format="示例";b.add("把故事带在身边","欢迎使用页间",true);b.add("这是可以安装的 Android 阅读器。书籍、阅读位置和译文保存在本机，不需要登录网站。点击书架右上方的导入按钮，选择 EPUB、TXT 或 DOCX。Android 15 及以上也可提取文字型 PDF。","欢迎使用页间",false);b.add("点击右侧或左滑翻到下一页，点击左侧或右滑返回。点击中央呼出菜单，再点击「样式」可以调整字体、字号、背景、行距和翻页间隔。自动翻页遇到较长内容时，会先缓慢向下滚动，再翻到下一页。","欢迎使用页间",false);b.add("在翻译设置里选择免费通道或 DeepSeek，点击「开启翻译」。程序只请求当前页和后面三页，已有译文不会重复请求。回到书架或切到后台会停止新请求；已经发送的请求会完成并缓存。","欢迎使用页间",false);b.add("A small journey","英文翻译体验",true);for(int n=0;n<5;n++){b.add("The little bookshop stood at the end of a quiet street. Every morning, its owner opened the blue shutters and placed a wooden chair beside the door. There was always a book waiting to be opened.","英文翻译体验",false);b.add("A traveler arrived with a notebook full of unfamiliar words. She asked for a story that would help her understand the place. The owner smiled and offered her the smallest book on the shelf.","英文翻译体验",false);b.add("She read one page, then another. By evening, the street outside felt less unfamiliar. Nothing had changed except the words she could now understand.","英文翻译体验",false);}b.add("下一段故事，由你带来","开始自己的阅读",true);b.add("本示例为原创文字。导入你的书，慢慢读。请定期在设置里备份书架，卸载应用会删除本机数据。","开始自己的阅读",false);return b;}
}
